ValidationRule.errorConditionFormula:
AND(
    OR(
        /* Block Rejected → Cancel ONLY for users WITH permission */
        AND(
            ISPICKVAL(PRIORVALUE(uAssist_Status__c), 'Rejected'),
            TEXT(uAssist_Status__c) = 'Cancel',
            $Permission.Bypass_uAssist_Status_Validation
        ),

        /* Block Case ready to review → Cancel OR Rejected (specific profiles) */
        AND(
            ISPICKVAL(PRIORVALUE(uAssist_Status__c), 'Case ready to review'),
            OR(
                TEXT(uAssist_Status__c) = 'Cancel',
                TEXT(uAssist_Status__c) = 'Rejected'
            ),
            OR(
                $Profile.Name = 'uLab uAssist Team',
                $Profile.Name = 'uLab uAssist Lead & Sr. Trainer',
                $Profile.Name = 'uLab uAssist Team/Clinical Review'
            )
        )
    )
)
